/**
 * lancerCharge.test.ts — Lancer charge mechanic tests.
 * BUG-B1: Empty if-block in ActPhase allows backward charge.
 *
 * Charge rule: Lancer can MOVE + ATTACK in the same turn,
 * but ONLY if the movement is toward the enemy half.
 * Backward move should forfeit the attack (set hasActed).
 */

import { describe, it, expect } from 'vitest';
import {
  createTestEngine,
  deployCard,
  skipTurn,
  injectHand,
  Player,
  TurnPhase,
} from '../helpers/TestHarness';

/**
 * Helper: deploy a lancer and advance to a turn where it can act.
 * Returns the test engine + lancer info, in P1's ACT phase.
 */
function setupLancerOnBoard(col = 3, row = 2) {
  const t = createTestEngine();

  // Accumulate LEG — lancer costs 4
  for (let i = 0; i < 6; i++) skipTurn(t.engine); // 3 full rounds → P1 has 6 LEG

  // Deploy lancer
  injectHand(t.engine, Player.P1, ['lancer', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
  const pos = deployCard(t, 'lancer', col, row);
  expect(pos).not.toBeNull();

  // End P1 turn, P2 turn, back to P1 ACT (so lancer isn't isJustPlaced)
  t.engine.endPlayPhase();
  t.engine.endActPhase();
  skipTurn(t.engine); // P2

  // P1 ACT phase
  t.engine.endPlayPhase();
  expect(t.state().turn.phase).toBe(TurnPhase.ACT);

  const lancer = t.findUnit('lancer', Player.P1);
  expect(lancer).not.toBeNull();

  return { t, lancer: lancer! };
}

describe('Lancer charge', () => {
  it('forward move preserves attack ability (charge works)', () => {
    const { t, lancer } = setupLancerOnBoard(3, 2);

    // Move forward (higher row = toward enemy for P1)
    const moved = t.engine.moveUnit(lancer.instanceId, 3, 3);
    expect(moved).toBe(true);

    // After forward move, lancer should STILL be able to attack
    const attacks = t.engine.getValidAttackSquares(lancer.instanceId);
    // canUnitAttack should return true (hasActed=false, hasMoved=true, canAttackAfterMove=true)
    // The specific attack squares depend on enemy positions, but the query shouldn't return empty
    // due to hasActed being set
    // We verify by checking that the engine allows attack queries (not blocked by hasActed)
    // The fact that attacks may be empty just means no enemies in range, which is fine
    // Key check: canUnitAttack returns true
    const lancerUnit = t.state().board.find(c => c.unit?.instanceId === lancer.instanceId)?.unit;
    expect(lancerUnit).toBeTruthy();
    expect(lancerUnit!.hasActed).toBe(false);
    expect(lancerUnit!.hasMoved).toBe(true);
    expect(lancerUnit!.canAttackAfterMove).toBe(true);
  });

  it('backward move forfeits attack (charge denied) — B1 regression', () => {
    const { t, lancer } = setupLancerOnBoard(3, 2);

    // Move backward (lower row = toward own half for P1)
    const moved = t.engine.moveUnit(lancer.instanceId, 3, 1);
    expect(moved).toBe(true);

    // After backward move, lancer should NOT be able to attack
    // The bug: empty if-block means hasActed is never set for backward charge
    const lancerUnit = t.state().board.find(c => c.unit?.instanceId === lancer.instanceId)?.unit;
    expect(lancerUnit).toBeTruthy();
    expect(lancerUnit!.hasActed).toBe(true); // THIS FAILS BEFORE B1 FIX
  });

  it('non-charge unit always ends turn after any move', () => {
    const t = createTestEngine();

    injectHand(t.engine, Player.P1, ['foot_soldier', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    const pos = deployCard(t, 'foot_soldier', 3, 2);
    expect(pos).not.toBeNull();

    // Skip to next P1 ACT
    t.engine.endPlayPhase();
    t.engine.endActPhase();
    skipTurn(t.engine);
    t.engine.endPlayPhase();

    const unit = t.findUnit('foot_soldier', Player.P1);
    expect(unit).not.toBeNull();

    const moved = t.engine.moveUnit(unit!.instanceId, 3, 1);
    expect(moved).toBe(true);
    const unitState = t.state().board.find(c => c.unit?.instanceId === unit!.instanceId)?.unit;
    expect(unitState).not.toBeNull();
    expect(unitState!.hasActed).toBe(true);
  });
});

tests/engine/phases/phaseTransitions.tes.source:
import { describe, it, expect, beforeEach } from 'vitest';
import { createTestEngine, skipTurn, Player, TurnPhase, EngineStatus } from '../helpers/TestHarness';
import type { TestEngine } from '../helpers/TestHarness';

let t: TestEngine;

beforeEach(() => { t = createTestEngine(); });

describe('Phase transitions', () => {
  it('starts in PLAY phase, P1 active', () => {
    const s = t.state();
    expect(s.turn.phase).toBe(TurnPhase.PLAY);
    expect(s.turn.activePlayer).toBe(Player.P1);
    expect(s.turn.turnNumber).toBe(1);
  });

  it('PLAY → ACT via endPlayPhase', () => {
    t.engine.endPlayPhase();
    expect(t.state().turn.phase).toBe(TurnPhase.ACT);
    expect(t.state().turn.activePlayer).toBe(Player.P1);
  });

  it('ACT → next player PLAY via endActPhase', () => {
    t.engine.endPlayPhase();
    t.engine.endActPhase();
    const s = t.state();
    expect(s.turn.activePlayer).toBe(Player.P2);
    expect(s.turn.phase).toBe(TurnPhase.PLAY);
  });

  it('full round: P1 turn + P2 turn → turn 2', () => {
    skipTurn(t.engine); // P1
    skipTurn(t.engine); // P2
    const s = t.state();
    expect(s.turn.turnNumber).toBe(2);
    expect(s.turn.activePlayer).toBe(Player.P1);
  });

  it('endPlayPhase is no-op during ACT', () => {
    t.engine.endPlayPhase();
    t.engine.endPlayPhase(); // no-op
    expect(t.state().turn.phase).toBe(TurnPhase.ACT);
  });

  it('endActPhase is no-op during PLAY', () => {
    t.engine.endActPhase(); // no-op
    expect(t.state().turn.phase).toBe(TurnPhase.PLAY);
  });

  it('emits PHASE_CHANGED events', () => {
    t.engine.endPlayPhase();
    const phaseEvents = t.eventsOfType('PHASE_CHANGED');
    expect(phaseEvents.length).toBeGreaterThanOrEqual(1);
    const last = phaseEvents[phaseEvents.length - 1] as any;
    expect(last.phase).toBe(TurnPhase.ACT);
  });

  it('emits TURN_STARTED on turn change', () => {
    skipTurn(t.engine);
    const turnEvents = t.eventsOfType('TURN_STARTED');
    // At least 2: initial + P2's turn
    expect(turnEvents.length).toBeGreaterThanOrEqual(2);
  });
});

describe('Phase guards with AWAITING_INPUT', () => {
  it('endPlayPhase blocked during AWAITING_INPUT', () => {
    // Play a Priest to trigger pending TARGET
    const priestIdx = t.findInHand('priest');
    if (priestIdx >= 0) {
      const pos = t.deployPositions()[0];
      t.engine.playCard(priestIdx, pos.col, pos.row);

      if (t.state().status === EngineStatus.AWAITING_INPUT) {
        t.engine.endPlayPhase(); // should be no-op
        expect(t.state().turn.phase).toBe(TurnPhase.PLAY);
      }
    }
  });
});

tests/engine/phases/counterAttack.test.t.source:
/**
 * counterAttack.test.ts — Counter-attack and dying blow mechanics.
 */

import { describe, it, expect } from 'vitest';
import {
  createTestEngine,
  deployCard,
  skipTurn,
  injectHand,
  Player,
  TurnPhase,
} from '../helpers/TestHarness';

describe('Counter-attack mechanics', () => {
  it('melee defender counter-attacks after surviving', () => {
    const t = createTestEngine();
    // Accumulate LEG for swordsman (cost ~4)
    for (let i = 0; i < 10; i++) skipTurn(t.engine);

    // Deploy P1 swordsman at row 2
    injectHand(t.engine, Player.P1, ['swordsman', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    const p1Pos = deployCard(t, 'swordsman', 3, 2);
    expect(p1Pos).not.toBeNull();
    t.engine.endPlayPhase(); t.engine.endActPhase();

    // P2's turn — deploy swordsman (deployCard auto-detects active player)
    injectHand(t.engine, Player.P2, ['swordsman', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    expect(deployCard(t, 'swordsman', 3, 5)).not.toBeNull();
    t.engine.endPlayPhase(); t.engine.endActPhase();

    // P1: move swordsman toward P2. Need to get adjacent.
    // P1 swordsman at (3,2), P2 swordsman at (3,5). Move P1 forward over multiple turns.
    t.engine.endPlayPhase();
    const p1u1 = t.findUnit('swordsman', Player.P1);
    expect(p1u1).not.toBeNull();
    t.engine.moveUnit(p1u1!.instanceId, 3, 3);
    t.engine.endActPhase();

    skipTurn(t.engine); // P2

    // P1 turn: move from (3,3) to (3,4)
    t.engine.endPlayPhase();
    const p1u2 = t.findUnit('swordsman', Player.P1);
    expect(p1u2).not.toBeNull();
    t.engine.moveUnit(p1u2!.instanceId, 3, 4);
    t.engine.endActPhase();

    skipTurn(t.engine); // P2

    // P1: now at (3,4), P2 at (3,5) — adjacent! Attack.
    t.engine.endPlayPhase();
    const attacker = t.findUnit('swordsman', Player.P1);
    const defender = t.findUnit('swordsman', Player.P2);
    expect(attacker).not.toBeNull();
    expect(defender).not.toBeNull();

    const eventsBefore = t.events.length;
    const attacked = t.engine.attackUnit(attacker!.instanceId, defender!.instanceId);
    expect(attacked).toBe(true);

    const combatEvents = t.events.slice(eventsBefore);
    const attacks = combatEvents.filter(e => e.type === 'UNIT_ATTACKED');
    // Primary + counter = 2 attack events (both swordsmen are melee)
    expect(attacks.length).toBe(2);
  });

  it('attack event order: primary attack before counter-attack', () => {
    const t = createTestEngine();
    for (let i = 0; i < 10; i++) skipTurn(t.engine);

    // Deploy adjacent combatants
    injectHand(t.engine, Player.P1, ['foot_soldier', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    expect(deployCard(t, 'foot_soldier', 3, 2)).not.toBeNull();
    t.engine.endPlayPhase(); t.engine.endActPhase();

    injectHand(t.engine, Player.P2, ['foot_soldier', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    expect(deployCard(t, 'foot_soldier', 3, 5)).not.toBeNull();
    t.engine.endPlayPhase(); t.engine.endActPhase();

    // Move P1 to row 3
    t.engine.endPlayPhase();
    const p1 = t.findUnit('foot_soldier', Player.P1);
    expect(p1).not.toBeNull();
    expect(t.engine.moveUnit(p1!.instanceId, 3, 3)).toBe(true);
    t.engine.endActPhase();
    skipTurn(t.engine);

    // Attack
    t.engine.endPlayPhase();
    const att = t.findUnit('foot_soldier', Player.P1);
    const def = t.findUnit('foot_soldier', Player.P2);
    expect(att).not.toBeNull();
    expect(def).not.toBeNull();

    const eventsBefore = t.events.length;
    t.engine.attackUnit(att!.instanceId, def!.instanceId);
    const combatEvents = t.events.slice(eventsBefore);
    const attacks = combatEvents.filter(e => e.type === 'UNIT_ATTACKED');

    if (attacks.length >= 2) {
      // First attack should be from P1 unit, second from P2 unit (counter)
      expect((attacks[0] as any).attackerInstanceId).toBe(att!.instanceId);
      expect((attacks[1] as any).attackerInstanceId).toBe(def!.instanceId);
    }
  });

  it('attack executes and produces UNIT_ATTACKED events', () => {
    const t = createTestEngine();
    for (let i = 0; i < 10; i++) skipTurn(t.engine);

    injectHand(t.engine, Player.P1, ['archer', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    expect(deployCard(t, 'archer', 3, 2)).not.toBeNull();
    t.engine.endPlayPhase(); t.engine.endActPhase();

    injectHand(t.engine, Player.P2, ['foot_soldier', 'foot_soldier', 'foot_soldier', 'foot_soldier']);
    expect(deployCard(t, 'foot_soldier', 3, 5)).not.toBeNull();
    t.engine.endPlayPhase(); t.engine.endActPhase();

    // Move archer
    t.engine.endPlayPhase();
    const archer = t.findUnit('archer', Player.P1);
    expect(archer).not.toBeNull();
    const moves = t.engine.getValidMoveSquares(archer!.instanceId);
    if (moves.length > 0) {
      t.engine.moveUnit(archer!.instanceId, moves[0].col, moves[0].row);
    }
    t.engine.endActPhase();
    skipTurn(t.engine);

    // Try attack
    t.engine.endPlayPhase();
    const arch = t.findUnit('archer', Player.P1);
    const target = t.findUnit('foot_soldier', Player.P2);
    expect(arch).not.toBeNull();
    expect(target).not.toBeNull();

    const eventsBefore = t.events.length;
    const result = t.engine.attackUnit(arch!.instanceId, target!.instanceId);
    if (result) {
      const combatEvents = t.events.slice(eventsBefore);
      expect(combatEvents.some(e => e.type === 'UNIT_ATTACKED')).toBe(true);
    }
    // If attack wasn't valid (out of range), that's OK — test verifies no crash
  });
});

tests/engine/abilities/onDeployDraw.test.source:
import { describe, it, expect, beforeEach } from 'vitest';
import { createTestEngine, deployCard, Player } from '../helpers/TestHarness';
import type { TestEngine } from '../helpers/TestHarness';

let t: TestEngine;

beforeEach(() => { t = createTestEngine(); });

describe('onDeployDraw — Scout and Messenger', () => {
  it('scout deploy emits SCOUT_RESULT (reveal opponent top cards)', () => {
    const scoutIdx = t.findInHand('scout');
    if (scoutIdx < 0) return;

    const pos = t.deployPositions()[0];
    if (!pos) return;

    const affordable = t.engine.getAffordableCards();
    if (!affordable.includes(scoutIdx)) return;

    t.engine.playCard(scoutIdx, pos.col, pos.row);

    const scoutEvents = t.eventsOfType('SCOUT_RESULT');
    expect(scoutEvents.length).toBeGreaterThan(0);
    const ev = scoutEvents[0] as any;
    expect(ev.topCards).toBeDefined();
  });

  it('messenger deploy draws 1 card', () => {
    const msgIdx = t.findInHand('messenger');
    if (msgIdx < 0) return;

    const pos = t.deployPositions()[0];
    if (!pos) return;

    const affordable = t.engine.getAffordableCards();
    if (!affordable.includes(msgIdx)) return;

    const handBefore = t.state().players[Player.P1].hand.length;
    const deckBefore = t.state().players[Player.P1].deckCount;

    t.engine.playCard(msgIdx, pos.col, pos.row);

    const handAfter = t.state().players[Player.P1].hand.length;
    const deckAfter = t.state().players[Player.P1].deckCount;

    // Played 1, drew 1 → net hand change = 0
    expect(handAfter).toBe(handBefore - 1 + 1);
    expect(deckAfter).toBe(deckBefore - 1);
  });

  it('foot_soldier has no on-deploy draw (it draws on death)', () => {
    const idx = t.findInHand('foot_soldier');
    if (idx < 0) return;

    const pos = t.deployPositions()[0];
    if (!pos) return;

    const affordable = t.engine.getAffordableCards();
    if (!affordable.includes(idx)) return;

    const drawsBefore = t.eventsOfType('CARD_DRAWN').length;
    t.engine.playCard(idx, pos.col, pos.row);

    // foot_soldier has ON_DEATH_DRAW, not ON_DEPLOY_DRAW
    // No draw events should fire from deploy
    const drawsAfter = t.eventsOfType('CARD_DRAWN').length;
    expect(drawsAfter).toBe(drawsBefore);
  });
});

